.profile-settings {
    /* FormRow's public CSS variable: wider label column so long labels fit on one line. */
    --gc-form-row-label-width: 220px;

    box-sizing: border-box;
    max-width: 840px;
    margin: 0 auto;
    padding: var(--g-spacing-8) var(--g-spacing-6);
}

.profile-settings__header {
    margin-block-end: var(--g-spacing-6);
}

.profile-settings__header h1,
.profile-settings__section-title {
    margin: 0;
}

.profile-settings__card {
    overflow: hidden;
}

.profile-settings__body {
    padding: 0 var(--g-spacing-6);
}

.profile-settings__section {
    padding: var(--g-spacing-6) 0 var(--g-spacing-1);
}

.profile-settings__section-title {
    display: block;
    margin-block-end: var(--g-spacing-4);
}

.profile-settings__avatar {
    position: relative; /* anchors the visually hidden file input */
}

.profile-settings__footer {
    padding: var(--g-spacing-4) var(--g-spacing-6);
    background: var(--g-color-base-generic-ultralight);
}

.profile-settings__status {
    flex: 1 1 auto;
    min-width: 0;
}

.profile-settings__actions {
    flex-shrink: 0;
    margin-inline-start: auto;
}

@media (max-width: 767px) {
    .profile-settings {
        padding: var(--g-spacing-5) var(--g-spacing-3);
    }

    .profile-settings__body,
    .profile-settings__footer {
        padding-inline: var(--g-spacing-4);
    }

    .profile-settings__status,
    .profile-settings__actions {
        flex-basis: 100%;
    }

    .profile-settings__actions > * {
        flex: 1;
    }
}

